CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS snapshot(id INTEGER PRIMARY KEY CHECK(id=1), body TEXT NOT NULL, etag TEXT NOT NULL, modified TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS monitoring(id INTEGER PRIMARY KEY CHECK(id=1), body TEXT NOT NULL);
INSERT OR IGNORE INTO monitoring VALUES(1,'{}');
CREATE TABLE IF NOT EXISTS subscriptions(chat INTEGER PRIMARY KEY,active INTEGER NOT NULL,generation INTEGER NOT NULL,baseline INTEGER NOT NULL,results_enabled INTEGER NOT NULL,milestones_enabled INTEGER NOT NULL,message_id INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS outbox(id INTEGER PRIMARY KEY AUTOINCREMENT,chat INTEGER NOT NULL REFERENCES subscriptions(chat),generation INTEGER NOT NULL,kind TEXT NOT NULL,milestone INTEGER NOT NULL,revision TEXT NOT NULL,text TEXT NOT NULL,due INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'pending',last_error TEXT NOT NULL DEFAULT '',UNIQUE(chat,kind,milestone));
CREATE INDEX IF NOT EXISTS outbox_due ON outbox(state,due);
CREATE TABLE IF NOT EXISTS command_offset(id INTEGER PRIMARY KEY CHECK(id=1),value INTEGER NOT NULL);
INSERT OR IGNORE INTO command_offset VALUES(1,0);
